    q(6, '①', '経度', '地球上の東西の位置を表すものを何というか。', T('経度', 'けいど'), '経度＝東西の位置。本初子午線が0度、東西それぞれ180度。', near=['緯度'])
    q(6, '①', '経度', '経度0度の経線を何というか。', T('本初子午線', 'ほんしょしごせん'), '本初子午線はイギリスのロンドン（旧グリニッジ天文台）を通る。', near=['赤道', '標準時子午線'])
    q(74, '㉘', '経度', '本初子午線が通る、イギリスの首都はどこか。', T('ロンドン', 'ろんどん'), 'ロンドンの旧グリニッジ天文台を通る。', near=['パリ'])
    q(6, '①', '経度', '本初子午線より東の経度を何というか。', T('東経', 'とうけい'), '本初子午線より東が東経、西が西経。', near=['西経', '北緯'])
    q(6, '①', '経度', '東経・西経の最大はそれぞれ何度か。', N(180, ['度', '°']), '東経・西経とも180度まで。東経180度と西経180度は同じ経線。', near=['90', '360'])
