    q(6, '①', '半球', '赤道より北側の半分を何というか。', T('北半球', 'きたはんきゅう'), '赤道を境に北半球・南半球。', near=['南半球', '東半球'])
    q(7, '①', '緯線と経線', '地球儀で、緯線と経線はどのような角度で交わっているか。', T('直角', '90度', 'ちょっかく', '垂直'), '緯線と経線は直角に交わる。', near=['45度'])
    # 対せき点
