def _clock(h, md=None):
    """時刻の答え（「午後1時」「13時」のどちらでも正解）。md は「1月1日」のような日付"""
    h %= 24
    ap = f'午前{h}時' if h < 12 else f'午後{h - 12}時'
    if h == 0: ap = '午前0時'
    if h == 12: ap = '午後0時'
    alts = [ap, f'{h}時']
    if h == 12: alts.append('正午')
    out = []
    for a in alts:
        if md:
            out += [f'{md}{a}', f'{md} {a}', f'{md}の{a}']
        else:
            out.append(a)
    return T(*out)

